export type Actions = {
  setTab: (tab: Tab) => unknown
  /** Lance la commande du skill (la suite du parcours). */
  launch: (skill: string) => unknown
  /** Met la commande du skill dans le prompt (lanceur : la personne ajoute le sujet). */
